def binomial_coefficient(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use the property C(n, k) = C(n-1, k-1) + C(n-1, k)
    prev = [1] * (k + 1)
    for i in range(1, n + 1):
        new = [1] * (k + 1)
        for j in range(1, min(i, k) + 1):
            new[j] = prev[j-1] + prev[j]
        prev = new
    return prev[k]

