from typing import List, Tuple

def cross_product(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> int:
    """Cross product of vectors (a-o) and (b-o). Positive for counter-clockwise."""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    """Compute convex hull using Monotone Chain algorithm."""
    if len(points) <= 1:
        return points[:]

    # Sort points lexicographically
    points.sort()

    # Build lower hull
    lower = []
    for p in points:
        while len(lower) >= 2 and cross_product(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    # Build upper hull
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross_product(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Concatenate and remove duplicates (last point appears twice)
    return lower[:-1] + upper[:-1]

