def strongly_connected_components(graph: dict[int, set[int]]) -> list[set[int]]:
    """
    Find all strongly connected components (SCCs) in a directed graph using Kosaraju's
    two-pass DFS. Returns a list of sets, each set being one SCC.
    """
    nodes = set(graph.keys())
    visited = set()
    stack = []

    def dfs_order(node):
        visited.add(node)
        for neighbor in graph.get(node, set()):
            if neighbor not in visited:
                dfs_order(neighbor)
        stack.append(node)

    # First pass: order nodes by finishing time.
    for node in nodes:
        if node not in visited:
            dfs_order(node)

    # Second pass: reverse edges and DFS in reverse order.
    reversed_graph = {node: {neighbor for neighbor, _ in graph.items() if node in neighbor} for node in nodes}
    components = []

    def dfs_component(node, component):
        visited.add(node)
        component.add(node)
        for neighbor in reversed_graph.get(node, set()):
            if neighbor not in visited:
                dfs_component(neighbor, component)

    while stack:
        node = stack.pop()
        if node not in visited:
            component = set()
            dfs_component(node, component)
            components.append(component)

    return components

