def articulation_points(n, edges):
    if n <= 1:
        return sorted(set(range(n)))

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    ap = [False] * n
    time = 0

    def dfs(u, visited, disc, low, parent, ap, time):
        nonlocal graph

        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        children = 0

        for v in graph[u]:
            if not visited[v]:
                children += 1
                parent[v] = u
                dfs(v, visited, disc, low, parent, ap, time)

                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    ap[u] = True
                if parent[u] != -1 and low[v] >= disc[u]:
                    ap[u] = True

        return ap

    ap = dfs(0, visited, disc, low, parent, ap, time)

    return sorted([i for i in range(n) if ap[i]])

def kmp_search(text, pattern):
    """
    Find all starting indices where pattern occurs in text using KMP algorithm.
    Returns list of indices [i, j, k, ...] where pattern starts at each position.
    """
    if not pattern:
        return list(range(len(text) + 1))

    # Build KMP failure function (border array)
    def build_failure():
        m = len(pattern)
        failure = [0] * m
        len_so_far = 0
        i = 1

        while i < m:
            if pattern[len_so_far] == pattern[i]:
                len_so_far += 1
                failure[i] = len_so_far
                i += 1
            else:
                if len_so_far != 0:
                    len_so_far = failure[len_so_far - 1]
                else:
                    failure[i] = 0
                    i += 1
        return failure

    failure = build_failure()
    n, m = len(text), len(pattern)
    indices = []

    i = 0  # text index
    j = 0  # pattern index

    while i < n:
        if pattern[j] == text[i]:
            i += 1
            j += 1
            if j == m:  # pattern found
                indices.append(i - j)
                j = failure[j - 1] if j > 0 else 0
        elif j != 0:
            j = failure[j - 1]
