class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1 << (self.n - 1).bit_length()  # next power of 2
        self.tree = [0] * (2 * self.size)
        self.build(data)

    def build(self, data):
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = self.tree[i << 1] + self.tree[i << 1 | 1]

    def update(self, i, val):
        i += self.size
        self.tree[i] = val
        while i > 1:
            i >>= 1
            self.tree[i] = self.tree[i << 1] + self.tree[i << 1 | 1]

    def query(self, l, r):
        l += self.size
        r += self.size
        res = 0
        while l <= r:
            if l & 1:
                res += self.tree[l]
                l >>= 1
            if r & 1:
                res += self.tree[r]
                r >>= 1
        return res
```

