function calculate_expression(expr) {
    // Remove spaces and validate basic structure
    expr = expr.replace(/\s+/g, '');
    if (!/^[0-9+\-*/()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Replace division with JavaScript division (truncates toward zero)
    expr = expr.replace(/\/\//g, '/');

    // Evaluate using stack-based infix evaluation
    const tokens = [];
    let num = '';

    for (let i = 0; i < expr.length; i++) {
        const c = expr[i];
        if (c >= '0' && c <= '9') {
            num += c;
        } else {
            if (num) {
                tokens.push(Number(num));
                num = '';
            }
            tokens.push(c);
        }
    }
    if (num) tokens.push(Number(num));

    // Process tokens with operator precedence
    const precedence = { '+': 1, '-': 1, '*': 2, '/': 2 };
    let stack = [];

    for (let token of tokens) {
        if (typeof token === 'number') {
            stack.push(token);
        } else if (token === '(') {
            stack.push(token);
        } else if (token === ')') {
            let result = stack.pop();
            while (stack.length > 0 && typeof stack[stack.length - 1] !== 'string' && stack[stack.length - 1] !== '(') {
                const op = stack.pop();
                const b = result;
                const a = stack.pop();
                result = op === '+' ? a + b : op === '-' ? a - b : op === '*' ? a * b : a / b;
            }
            stack.push(result);
        } else {
            while (stack.length > 0 && typeof stack[stack.length - 1] === 'number' && 
                   precedence[stack[stack.length - 1]] >= precedence[token]) {
                stack.pop();
            }
            stack.push(token);
        }
    }

    return stack.length === 1 ? stack[0] : 0;
}
```

