import re
from typing import Dict, List, Set

CRON_PATTERN = re.compile(
    r"""
    ^(?P<minute>[\*0-59]{1,6})\s+  # minute: *, 0-59, ranges, steps, lists
    (?P<hour>[\*0-23]{1,6})\s+   # hour: *, 0-23, ranges, steps, lists
    (?P<day>[\*1-31]{1,11})\s+   # day-of-month: *, 1-31, ranges, steps, lists
    (?P<month>[\*1-12]{1,7})\s+  # month: *, 1-12, ranges, steps, lists
    (?P<weekday>[\*0-6]{1,6})$  # day-of-week: *, 0-6, ranges, steps, lists
    """,
    re.VERBOSE,
)


def parse_cron(cron_str: str) -> Dict[str, List[int]]:
    """Parse a full 5-field cron expression into a dict of valid values."""
    match = CRON_PATTERN.fullmatch(cron_str.strip())
    if not match:
        raise ValueError(f"Invalid cron format: {cron_str}")

    def parse_field(field: str) -> List[int]:
        values: Set[int] = set()
        parts = re.split(r"[-/,\s]+", field)

        for part in parts:
            if part == "*":
                values.update(range(0, 60, 1))
            elif "-" in part:
                start, end = map(int, part.split("-"))
                if start > end:
                    raise ValueError(f"Invalid range: {part}")
                values.update(range(start, end + 1))
            elif "/" in part:
                step = int(part.split("/")[1])
                values.update(range(0, 60, step))
            elif "," in part:
                values.update(int(x) for x in part.split(","))
            else:
                values.add(int(part))

        return sorted(values)

    return {
        "minute": parse_field(match.group("minute")),
        "hour": parse_field(match.group("hour")),
        "day": parse_field(match.group("day")),
        "month": parse_field(match.group("month")),
        "weekday": parse_field(match.group("weekday")),
    }
